import ajax from '@/utils/ajax';
import { observable, action, makeObservable } from 'mobx';


class Store {
    @observable selectId = "app";
    @action setSelectId = (key) => {
        this.selectId = key;
    }


    @observable initValues = null;
    @action setInitValues = (vals) => {
        this.initValues = vals;
    }

    @observable list = [];

    @action setList = (list) => {
        this.list = list;
    }


    init = () => {
        return ajax.post("/apijson/get", {
            [`Application[]`]: {
                "count": 0,
                Application: {
                    "@order": "sort+"
                }
            }
        }).then((res) => {
            this.setList(res.Application);
        })
    }

    constructor() {
        makeObservable(this);
    }
}

export default new Store();