import React from "react";
import styles from './index.module.less';
import { useObserver } from 'mobx-react-lite';
import { Grid, Image, Message, Popover, Space } from "@arco-design/web-react";
import { IconDelete, IconEdit } from "@arco-design/web-react/icon";
import store from '../../store';
import ajax from "@/utils/ajax";


interface AppCardProps {
    data: any;
}

const AppCard = ({ data }: AppCardProps) => {


    return useObserver(() => {

        return (
            <Grid.Col span={4}>
                <div className={styles.AppCard}
                    onClick={() => {
                        window.open(`#/app/${data.mark}/`)
                    }}
                >
                    <div className={styles.imgView}>
                        <Image
                            width="100%"
                            height="100%"
                            className={styles.appImage}
                            preview={false}
                            src={data.logoUrl}
                        />
                    </div>
                    <div className={styles.title}>
                        {data.name}
                    </div>
                    <Space className={styles.setting}>
                        <Popover content="删除应用" position="right">
                            <IconDelete
                                onClick={(e) => {
                                    e.stopPropagation();
                                    Message.info("暂不支持删除应用")
                                    // ajax.post('/apijson/delete', {
                                    //     Application: {
                                    //         id: data.id,
                                    //     }
                                    // })
                                }}
                            />
                        </Popover>
                        <Popover content="更新应用" position="right">
                            <IconEdit
                                onClick={(e) => {
                                    e.stopPropagation();
                                    store.setInitValues(data)
                                }}
                            />
                        </Popover>
                    </Space>
                </div>
            </Grid.Col>
        )

    })
}

export default AppCard;